class Trie:
    def __init__(self):
        self.root = {}

    def add(self, word):
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node["$"] = True

    def starts_with(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node:
                return []
            node = node[ch]
        found = []
        stack = [(node, prefix)]
        while stack:
            node, word = stack.pop()
            for key, child in node.items():
                if key == "$":
                    found.append(word)
                else:
                    stack.append((child, word + key))
        return sorted(found)

